// main.zig — swscale candidate: pixel-format conversion and scaling behind the
// three-function C ABI of swscale_api.h.
//
// The arithmetic follows libswscale's scalar pipeline (BT.601, limited-range YUV,
// full-range gray, 15-bit intermediates, 12-bit vertical taps) so the output
// tracks the reference; the inner loops are written with @Vector.

const std = @import("std");
const flt = @import("filter.zig");
const k = @import("kernels.zig");

const alloc = std.heap.c_allocator;

pub const YUV420P = 0;
pub const YUV422P = 1;
pub const YUV444P = 2;
pub const NV12 = 3;
pub const NV21 = 4;
pub const RGB24 = 5;
pub const BGR24 = 6;
pub const RGBA = 7;
pub const BGRA = 8;
pub const GRAY8 = 9;

fn isRGB(f: i32) bool {
    return f >= RGB24 and f <= BGRA;
}
fn isPlanarYUV(f: i32) bool {
    return f == YUV420P or f == YUV422P or f == YUV444P;
}
fn isNV(f: i32) bool {
    return f == NV12 or f == NV21;
}
fn hasAlpha(f: i32) bool {
    return f == RGBA or f == BGRA;
}
fn chrHSub(f: i32) u5 {
    return switch (f) {
        YUV420P, YUV422P, NV12, NV21 => 1,
        else => 0,
    };
}
fn chrVSub(f: i32) u5 {
    return switch (f) {
        YUV420P, NV12, NV21 => 1,
        else => 0,
    };
}
fn ceilShift(v: i32, s: u5) i32 {
    return -((-v) >> s);
}

const Mode = enum { copy, yuv2rgb_table, planar_to_nv, nv_to_planar, bgr24_to_yv12, rgb_to_rgb, generic };

const RangeConv = enum { none, to_jpeg, from_jpeg };

pub const Ctx = struct {
    sw: i32,
    sh: i32,
    sf: i32,
    dw: i32,
    dh: i32,
    df: i32,
    algo: i32,
    mode: Mode,

    // colour tables
    yc: k.YuvRgb = undefined,
    rgb2yuv: k.RgbYuv = undefined,

    // generic pipeline
    full_chr: bool = false,
    chr_src_hsub: u5 = 0,
    chr_src_vsub: u5 = 0,
    chr_dst_hsub: u5 = 0,
    chr_dst_vsub: u5 = 0,
    chr_src_w: i32 = 0,
    chr_src_h: i32 = 0,
    chr_dst_w: i32 = 0,
    chr_dst_h: i32 = 0,
    needs_hcscale: bool = true,
    need_alpha: bool = false,
    lum_range: RangeConv = .none,
    hlum: flt.Filter = undefined,
    hchr: flt.Filter = undefined,
    vlum: flt.Filter = undefined,
    vchr: flt.Filter = undefined,
    have_filters: bool = false,

    // ring buffers of horizontally scaled lines
    lum_ring: [][]i16 = &.{},
    alp_ring: [][]i16 = &.{},
    u_ring: [][]i16 = &.{},
    v_ring: [][]i16 = &.{},
    // scratch
    tmp_a: []i16 = &.{},
    tmp_b: []i16 = &.{},
    tmp_c: []i16 = &.{},
    tmp8_a: []u8 = &.{},
    tmp8_b: []u8 = &.{},
    yv: []i32 = &.{},
    uv: []i32 = &.{},
    vv: []i32 = &.{},
    av: []i32 = &.{},
    rows_l: [][*]const i16 = &.{},
    rows_c0: [][*]const i16 = &.{},
    rows_c1: [][*]const i16 = &.{},
    rows_a: [][*]const i16 = &.{},
};

fn allocRing(n: usize, w: usize) ![][]i16 {
    const r = try alloc.alloc([]i16, n);
    for (r) |*l| {
        l.* = try alloc.alloc(i16, w + 64);
        @memset(l.*, 0);
    }
    return r;
}

fn freeRing(r: [][]i16) void {
    for (r) |l| alloc.free(l);
    if (r.len > 0) alloc.free(r);
}

fn setupGeneric(c: *Ctx) !void {
    const sw = c.sw;
    const sh = c.sh;
    const dw = c.dw;
    const dh = c.dh;
    const src_gray = c.sf == GRAY8;
    const dst_gray = c.df == GRAY8;
    const src_range: i32 = if (src_gray) 1 else 0;
    const dst_range: i32 = if (dst_gray) 1 else 0;
    if (src_range != dst_range and !isRGB(c.df)) {
        c.lum_range = if (src_range == 1) .from_jpeg else .to_jpeg;
    }
    c.chr_src_hsub = chrHSub(c.sf);
    c.chr_src_vsub = chrVSub(c.sf);
    c.chr_dst_hsub = chrHSub(c.df);
    c.chr_dst_vsub = chrVSub(c.df);
    if (isRGB(c.df)) {
        if ((dw & 1) != 0) c.full_chr = true;
        if (c.chr_src_hsub == 0 and c.chr_src_vsub == 0) c.full_chr = true;
        if (!c.full_chr) c.chr_dst_hsub = 1;
    }
    if (isRGB(c.sf) and (dw >> c.chr_dst_hsub) <= (sw >> 1)) c.chr_src_hsub = 1;
    c.chr_src_w = ceilShift(sw, c.chr_src_hsub);
    c.chr_src_h = ceilShift(sh, c.chr_src_vsub);
    c.chr_dst_w = ceilShift(dw, c.chr_dst_hsub);
    c.chr_dst_h = ceilShift(dh, c.chr_dst_vsub);
    c.needs_hcscale = !(src_gray or dst_gray);
    c.need_alpha = hasAlpha(c.sf) and hasAlpha(c.df);

    const lumXInc: i64 = @divTrunc((@as(i64, sw) << 16) + (dw >> 1), dw);
    const lumYInc: i64 = @divTrunc((@as(i64, sh) << 16) + (dh >> 1), dh);
    const chrXInc: i64 = @divTrunc((@as(i64, c.chr_src_w) << 16) + (c.chr_dst_w >> 1), c.chr_dst_w);
    const chrYInc: i64 = @divTrunc((@as(i64, c.chr_src_h) << 16) + (c.chr_dst_h >> 1), c.chr_dst_h);
    const p0 = flt.localPos(0, 0);
    c.hlum = try flt.initFilter(alloc, lumXInc, sw, dw, 1 << 14, c.algo, p0, p0);
    c.hchr = try flt.initFilter(alloc, chrXInc, c.chr_src_w, c.chr_dst_w, 1 << 14, c.algo, flt.localPos(c.chr_src_hsub, -513), flt.localPos(c.chr_dst_hsub, -513));
    c.vlum = try flt.initFilter(alloc, lumYInc, sh, dh, 1 << 12, c.algo, p0, p0);
    c.vchr = try flt.initFilter(alloc, chrYInc, c.chr_src_h, c.chr_dst_h, 1 << 12, c.algo, flt.localPos(c.chr_src_vsub, -513), flt.localPos(c.chr_dst_vsub, -513));
    c.have_filters = true;

    const dwu: usize = @intCast(dw);
    const cdw: usize = @intCast(c.chr_dst_w);
    c.lum_ring = try allocRing(c.vlum.size, dwu);
    if (c.need_alpha) c.alp_ring = try allocRing(c.vlum.size, dwu);
    c.u_ring = try allocRing(c.vchr.size, cdw);
    c.v_ring = try allocRing(c.vchr.size, cdw);
    if (!c.needs_hcscale) {
        for (c.u_ring) |l| @memset(l, 1 << 14);
        for (c.v_ring) |l| @memset(l, 1 << 14);
    }
    const swu: usize = @intCast(sw);
    c.tmp_a = try alloc.alloc(i16, swu + 64);
    c.tmp_b = try alloc.alloc(i16, swu + 64);
    c.tmp_c = try alloc.alloc(i16, swu + 64);
    c.tmp8_a = try alloc.alloc(u8, swu + 64);
    c.tmp8_b = try alloc.alloc(u8, swu + 64);
    const wmax = @max(dwu, cdw) + 64;
    c.yv = try alloc.alloc(i32, wmax);
    c.uv = try alloc.alloc(i32, wmax);
    c.vv = try alloc.alloc(i32, wmax);
    c.av = try alloc.alloc(i32, wmax);
    c.rows_l = try alloc.alloc([*]const i16, c.vlum.size);
    c.rows_a = try alloc.alloc([*]const i16, c.vlum.size);
    c.rows_c0 = try alloc.alloc([*]const i16, c.vchr.size);
    c.rows_c1 = try alloc.alloc([*]const i16, c.vchr.size);
}

fn selectMode(c: *Ctx) Mode {
    const same = c.sw == c.dw and c.sh == c.dh;
    if (!same) return .generic;
    const s = c.sf;
    const d = c.df;
    if (s == d) return .copy;
    if ((s == YUV420P or s == YUV422P) and isRGB(d) and (c.dh & 1) == 0) return .yuv2rgb_table;
    if (s == YUV420P and isNV(d)) return .planar_to_nv;
    if (isNV(s) and d == YUV420P) return .nv_to_planar;
    if (s == BGR24 and d == YUV420P and (c.dw & 1) == 0) return .bgr24_to_yv12;
    if (isRGB(s) and isRGB(d)) return .rgb_to_rgb;
    return .generic;
}

fn createImpl(sw: c_int, sh: c_int, sf: c_int, dw: c_int, dh: c_int, df: c_int, algo: c_int) !*Ctx {
    if (sw < 1 or sh < 1 or dw < 1 or dh < 1) return error.Invalid;
    if (sf < 0 or sf > 9 or df < 0 or df > 9 or algo < 0 or algo > 2) return error.Invalid;
    const c = try alloc.create(Ctx);
    c.* = .{ .sw = sw, .sh = sh, .sf = sf, .dw = dw, .dh = dh, .df = df, .algo = algo, .mode = .generic };
    c.mode = selectMode(c);
    c.rgb2yuv = k.RgbYuv.init();
    c.yc = k.YuvRgb.init(c.sf == GRAY8);
    if (c.mode == .generic) try setupGeneric(c);
    if (c.mode == .yuv2rgb_table) {
        const w: usize = @intCast(sw);
        c.yv = try alloc.alloc(i32, w + 64);
        c.uv = try alloc.alloc(i32, w + 64);
        c.vv = try alloc.alloc(i32, w + 64);
    }
    return c;
}

export fn swscale_create(sw: c_int, sh: c_int, sf: c_int, dw: c_int, dh: c_int, df: c_int, algo: c_int) ?*anyopaque {
    const c = createImpl(sw, sh, sf, dw, dh, df, algo) catch return null;
    return @ptrCast(c);
}

export fn swscale_destroy(handle: ?*anyopaque) void {
    const c: *Ctx = @ptrCast(@alignCast(handle orelse return));
    if (c.have_filters) {
        c.hlum.deinit(alloc);
        c.hchr.deinit(alloc);
        c.vlum.deinit(alloc);
        c.vchr.deinit(alloc);
    }
    freeRing(c.lum_ring);
    freeRing(c.alp_ring);
    freeRing(c.u_ring);
    freeRing(c.v_ring);
    inline for (.{ "tmp_a", "tmp_b", "tmp_c", "tmp8_a", "tmp8_b", "yv", "uv", "vv", "av", "rows_l", "rows_a", "rows_c0", "rows_c1" }) |name| {
        if (@field(c, name).len > 0) alloc.free(@field(c, name));
    }
    alloc.destroy(c);
}

const Planes = struct {
    p: [4]?[*]u8,
    s: [4]isize,
    fn row(self: Planes, i: usize, y: isize) [*]u8 {
        return self.p[i].? + @as(usize, @intCast(y * self.s[i]));
    }
};

export fn swscale_process(
    handle: ?*anyopaque,
    src_data: [*]const ?[*]const u8,
    src_stride: [*]const c_int,
    dst_data: [*]const ?[*]u8,
    dst_stride: [*]const c_int,
) c_int {
    const c: *Ctx = @ptrCast(@alignCast(handle orelse return -1));
    var sp: Planes = undefined;
    var dp: Planes = undefined;
    for (0..4) |i| {
        sp.p[i] = @constCast(src_data[i]);
        sp.s[i] = src_stride[i];
        dp.p[i] = dst_data[i];
        dp.s[i] = dst_stride[i];
    }
    if (sp.p[0] == null or dp.p[0] == null) return -1;
    switch (c.mode) {
        .copy => doCopy(c, sp, dp),
        .yuv2rgb_table => doYuv2RgbTable(c, sp, dp),
        .planar_to_nv => doPlanarToNv(c, sp, dp),
        .nv_to_planar => doNvToPlanar(c, sp, dp),
        .bgr24_to_yv12 => doBgr24ToYv12(c, sp, dp),
        .rgb_to_rgb => doRgbToRgb(c, sp, dp),
        .generic => doGeneric(c, sp, dp),
    }
    return 0;
}

// ── unscaled special converters ─────────────────────────────────────────────

fn copyPlane(sp: Planes, si: usize, dp: Planes, di: usize, wbytes: usize, h: usize) void {
    for (0..h) |y| {
        const yy: isize = @intCast(y);
        @memcpy(dp.row(di, yy)[0..wbytes], sp.row(si, yy)[0..wbytes]);
    }
}

fn rowBytes(f: i32, w: i32, plane: usize) usize {
    const wu: usize = @intCast(w);
    const cw: usize = @intCast(ceilShift(w, 1));
    return switch (f) {
        YUV420P, YUV422P => if (plane == 0) wu else cw,
        NV12, NV21 => if (plane == 0) wu else cw * 2,
        RGB24, BGR24 => wu * 3,
        RGBA, BGRA => wu * 4,
        else => wu,
    };
}
fn planeRows(f: i32, h: i32, plane: usize) usize {
    if (plane == 0) return @intCast(h);
    return @intCast(if (chrVSub(f) == 1) ceilShift(h, 1) else h);
}
fn planeCount(f: i32) usize {
    return switch (f) {
        YUV420P, YUV422P, YUV444P => 3,
        NV12, NV21 => 2,
        else => 1,
    };
}

fn doCopy(c: *Ctx, sp: Planes, dp: Planes) void {
    for (0..planeCount(c.sf)) |p| copyPlane(sp, p, dp, p, rowBytes(c.sf, c.sw, p), planeRows(c.sf, c.sh, p));
}

fn doPlanarToNv(c: *Ctx, sp: Planes, dp: Planes) void {
    copyPlane(sp, 0, dp, 0, @intCast(c.sw), @intCast(c.sh));
    const cw: usize = @intCast(ceilShift(c.sw, 1));
    const ch: usize = @intCast(ceilShift(c.sh, 1));
    const swap = c.df == NV21;
    for (0..ch) |y| {
        const yy: isize = @intCast(y);
        const u = sp.row(1, yy);
        const v = sp.row(2, yy);
        k.interleave(dp.row(1, yy), if (swap) v else u, if (swap) u else v, cw);
    }
}

fn doNvToPlanar(c: *Ctx, sp: Planes, dp: Planes) void {
    copyPlane(sp, 0, dp, 0, @intCast(c.sw), @intCast(c.sh));
    const cw: usize = @intCast(ceilShift(c.sw, 1));
    const ch: usize = @intCast(ceilShift(c.sh, 1));
    const swap = c.sf == NV21;
    for (0..ch) |y| {
        const yy: isize = @intCast(y);
        const u = dp.row(1, yy);
        const v = dp.row(2, yy);
        k.deinterleave(sp.row(1, yy), if (swap) v else u, if (swap) u else v, cw);
    }
}

fn doBgr24ToYv12(c: *Ctx, sp: Planes, dp: Planes) void {
    const w: usize = @intCast(c.sw);
    var y: usize = 0;
    const h: usize = @intCast(c.sh);
    while (y + 1 < h + 1 and y < h) : (y += 2) {
        const yy: isize = @intCast(y);
        k.bgr24ToYv12Rows(&c.rgb2yuv, sp.row(0, yy), sp.row(0, yy + 1), dp.row(0, yy), dp.row(0, yy + 1), dp.row(1, yy >> 1), dp.row(2, yy >> 1), w);
    }
}

fn doRgbToRgb(c: *Ctx, sp: Planes, dp: Planes) void {
    const w: usize = @intCast(c.sw);
    for (0..@as(usize, @intCast(c.sh))) |y| {
        const yy: isize = @intCast(y);
        k.rgbToRgbRow(c.sf, c.df, sp.row(0, yy), dp.row(0, yy), w);
    }
}

fn doYuv2RgbTable(c: *Ctx, sp: Planes, dp: Planes) void {
    const w: usize = @intCast(c.dw);
    const vs: u5 = chrVSub(c.sf);
    for (0..@as(usize, @intCast(c.dh))) |y| {
        const yy: isize = @intCast(y);
        const cy = yy >> vs;
        k.yuv2rgbTableRow(&c.yc, c.df, sp.row(0, yy), sp.row(1, cy), sp.row(2, cy), dp.row(0, yy), w);
    }
}

// ── generic scaler ──────────────────────────────────────────────────────────

fn lumLine(c: *Ctx, sp: Planes, r: i32, out: []i16) void {
    const sw: usize = @intCast(c.sw);
    const dw: usize = @intCast(c.dw);
    const srow = sp.row(0, r);
    if (isRGB(c.sf)) {
        if (c.hlum.identity) {
            k.rgbToY(&c.rgb2yuv, c.sf, srow, out.ptr, sw, true);
        } else {
            k.rgbToY(&c.rgb2yuv, c.sf, srow, c.tmp_a.ptr, sw, false);
            k.hscale16(out.ptr, dw, c.tmp_a.ptr, &c.hlum);
        }
    } else {
        if (c.hlum.identity) {
            k.u8ToI15(out.ptr, srow, dw);
        } else {
            k.hscale8(out.ptr, dw, srow, &c.hlum);
        }
    }
    switch (c.lum_range) {
        .none => {},
        .to_jpeg => k.lumRangeToJpeg(out[0..dw]),
        .from_jpeg => k.lumRangeFromJpeg(out[0..dw]),
    }
}

fn alpLine(c: *Ctx, sp: Planes, r: i32, out: []i16) void {
    const sw: usize = @intCast(c.sw);
    const dw: usize = @intCast(c.dw);
    k.rgbaToA(sp.row(0, r), c.tmp_a.ptr, sw);
    k.hscale16(out.ptr, dw, c.tmp_a.ptr, &c.hlum);
}

fn chrLine(c: *Ctx, sp: Planes, r: i32, ou: []i16, ov: []i16) void {
    const csw: usize = @intCast(c.chr_src_w);
    const cdw: usize = @intCast(c.chr_dst_w);
    if (isRGB(c.sf)) {
        const srow = sp.row(0, r);
        if (c.chr_src_hsub == 1) {
            k.rgbToUVHalf(&c.rgb2yuv, c.sf, srow, c.tmp_b.ptr, c.tmp_c.ptr, csw);
        } else {
            k.rgbToUV(&c.rgb2yuv, c.sf, srow, c.tmp_b.ptr, c.tmp_c.ptr, csw);
        }
        k.hscale16(ou.ptr, cdw, c.tmp_b.ptr, &c.hchr);
        k.hscale16(ov.ptr, cdw, c.tmp_c.ptr, &c.hchr);
    } else {
        var su: [*]const u8 = undefined;
        var sv: [*]const u8 = undefined;
        if (isNV(c.sf)) {
            const swap = c.sf == NV21;
            k.deinterleave(sp.row(1, r), if (swap) c.tmp8_b.ptr else c.tmp8_a.ptr, if (swap) c.tmp8_a.ptr else c.tmp8_b.ptr, csw);
            su = c.tmp8_a.ptr;
            sv = c.tmp8_b.ptr;
        } else {
            su = sp.row(1, r);
            sv = sp.row(2, r);
        }
        if (c.hchr.identity) {
            k.u8ToI15(ou.ptr, su, cdw);
            k.u8ToI15(ov.ptr, sv, cdw);
        } else {
            k.hscale8(ou.ptr, cdw, su, &c.hchr);
            k.hscale8(ov.ptr, cdw, sv, &c.hchr);
        }
    }
    switch (c.lum_range) {
        .none => {},
        .to_jpeg => k.chrRangeToJpeg(ou[0..cdw], ov[0..cdw]),
        .from_jpeg => k.chrRangeFromJpeg(ou[0..cdw], ov[0..cdw]),
    }
}

fn doGeneric(c: *Ctx, sp: Planes, dp: Planes) void {
    const dh: usize = @intCast(c.dh);
    const dwu: usize = @intCast(c.dw);
    const cdw: usize = @intCast(c.chr_dst_w);
    const ls = c.vlum.size;
    const cs = c.vchr.size;
    var last_lum: i32 = -1;
    var last_chr: i32 = -1;
    const planar_out = isPlanarYUV(c.df) or isNV(c.df) or c.df == GRAY8;
    const chr_mask: usize = (@as(usize, 1) << c.chr_dst_vsub) - 1;

    for (0..dh) |dy| {
        // luma rows
        const lp = c.vlum.pos[dy];
        var r: i32 = @max(last_lum + 1, lp);
        while (r < lp + @as(i32, @intCast(ls))) : (r += 1) {
            const slot: usize = @intCast(@mod(r, @as(i32, @intCast(ls))));
            lumLine(c, sp, r, c.lum_ring[slot]);
            if (c.need_alpha) alpLine(c, sp, r, c.alp_ring[slot]);
        }
        last_lum = @max(last_lum, lp + @as(i32, @intCast(ls)) - 1);
        for (0..ls) |j| {
            const rr: i32 = lp + @as(i32, @intCast(j));
            const slot: usize = @intCast(@mod(rr, @as(i32, @intCast(ls))));
            c.rows_l[j] = c.lum_ring[slot].ptr;
            if (c.need_alpha) c.rows_a[j] = c.alp_ring[slot].ptr;
        }
        const lf = c.vlum.coef[dy * ls .. dy * ls + ls];

        const do_chr = !planar_out or ((dy & chr_mask) == 0 and c.df != GRAY8);
        const cy: usize = dy >> c.chr_dst_vsub;
        var cf: []const i16 = &.{};
        if (do_chr) {
            const cp = c.vchr.pos[cy];
            if (c.needs_hcscale) {
                var rc: i32 = @max(last_chr + 1, cp);
                while (rc < cp + @as(i32, @intCast(cs))) : (rc += 1) {
                    const slot: usize = @intCast(@mod(rc, @as(i32, @intCast(cs))));
                    chrLine(c, sp, rc, c.u_ring[slot], c.v_ring[slot]);
                }
                last_chr = @max(last_chr, cp + @as(i32, @intCast(cs)) - 1);
            }
            for (0..cs) |j| {
                const rr: i32 = cp + @as(i32, @intCast(j));
                const slot: usize = @intCast(@mod(rr, @as(i32, @intCast(cs))));
                c.rows_c0[j] = c.u_ring[slot].ptr;
                c.rows_c1[j] = c.v_ring[slot].ptr;
            }
            cf = c.vchr.coef[cy * cs .. cy * cs + cs];
        }

        const dyi: isize = @intCast(dy);
        if (planar_out) {
            const drow = dp.row(0, dyi);
            if (ls == 1) k.plane1(drow, c.rows_l[0], dwu) else k.planeX(drow, c.rows_l, lf, dwu, c.yv);
            if (do_chr) {
                const cyi: isize = @intCast(cy);
                if (isNV(c.df)) {
                    k.nv12cX(dp.row(1, cyi), c.rows_c0, c.rows_c1, cf, cdw, c.df == NV21, c.uv, c.vv);
                } else if (cs == 1) {
                    k.plane1(dp.row(1, cyi), c.rows_c0[0], cdw);
                    k.plane1(dp.row(2, cyi), c.rows_c1[0], cdw);
                } else {
                    k.planeX(dp.row(1, cyi), c.rows_c0, cf, cdw, c.uv);
                    k.planeX(dp.row(2, cyi), c.rows_c1, cf, cdw, c.vv);
                }
            }
        } else {
            k.packedVertical(c.full_chr, c.need_alpha, c.rows_l, lf, c.rows_c0, c.rows_c1, cf, c.rows_a, dwu, cdw, c.yv, c.uv, c.vv, c.av);
            if (c.full_chr) {
                k.writeFull(&c.yc, c.df, c.need_alpha, dp.row(0, dyi), c.yv, c.uv, c.vv, c.av, dwu);
            } else {
                k.writeHalf(&c.yc, c.df, dp.row(0, dyi), c.yv, c.uv, c.vv, dwu);
            }
        }
    }
}

