pub fn writeHalf(t: *const YuvRgb, f: i32, dst: [*]u8, yv: []const i32, uv: []const i32, vv: []const i32, w: usize) void {
    switch (f) {
        inline RGB24, BGR24, RGBA, BGRA => |ff| halfT(ff, t, dst, yv, uv, vv, w),
        else => unreachable,
    }
}

inline fn fullCh(v: V16i32) V16u8 {
    const s: @Vector(16, u5) = @splat(22);
    return @intCast(@min(@max(v, sp16(0)), sp16((1 << 30) - 1)) >> s);
}

fn fullT(comptime f: i32, comptime alpha: bool, t: *const YuvRgb, dst: [*]u8, yv: []const i32, uv: []const i32, vv: []const i32, av: []const i32, w: usize) void {
    const l = comptime layout(f);
    var i: usize = 0;
    while (i + 16 <= w) : (i += 16) {
        const Yr: V16i32 = yv[i..][0..16].*;
        const U: V16i32 = uv[i..][0..16].*;
        const V: V16i32 = vv[i..][0..16].*;
        const Y = (Yr -% sp16(t.y_off)) *% sp16(t.y_coef) +% sp16(1 << 21);
        const R = Y +% V *% sp16(t.v2r);
        const G = Y +% V *% sp16(t.v2g) +% U *% sp16(t.u2g);
        const B = Y +% U *% sp16(t.u2b);
        var a: V16u8 = @splat(255);
        if (alpha and l.bpp == 4) {
            const A: V16i32 = av[i..][0..16].*;
            const big = (A & sp16(0x100)) != sp16(0);
            const sel = @select(i32, big, @min(@max(A, sp16(0)), sp16(255)), A);
            a = @truncate(@as(@Vector(16, u32), @bitCast(sel)));
        }
        store16(f, dst + i * l.bpp, .{ .r = fullCh(R), .g = fullCh(G), .b = fullCh(B) }, a);
    }
    while (i < w) : (i += 1) {
        var Y: i32 = yv[i] -% t.y_off;
        Y = Y *% t.y_coef;
        Y +%= 1 << 21;
        const U = uv[i];
        const V = vv[i];
        var R: i32 = Y +% V *% t.v2r;
        var G: i32 = Y +% V *% t.v2g +% U *% t.u2g;
        var B: i32 = Y +% U *% t.u2b;
        if (((R | G | B) & @as(i32, @bitCast(@as(u32, 0xC0000000)))) != 0) {
            R = clip30(R);
            G = clip30(G);
            B = clip30(B);
        }
        const d = dst + i * l.bpp;
        d[l.r] = @intCast(R >> 22);
        d[1] = @intCast(G >> 22);
        d[l.b] = @intCast(B >> 22);
        if (l.bpp == 4) {
            if (alpha) {
                var A = av[i];
                if ((A & 0x100) != 0) A = @min(@max(A, 0), 255);
                d[3] = @truncate(@as(u32, @bitCast(A)));
            } else d[3] = 255;
        }
    }
}

pub fn writeFull(t: *const YuvRgb, f: i32, alpha: bool, dst: [*]u8, yv: []const i32, uv: []const i32, vv: []const i32, av: []const i32, w: usize) void {
    if (alpha) {
        switch (f) {
            inline RGBA, BGRA => |ff| fullT(ff, true, t, dst, yv, uv, vv, av, w),
            else => unreachable,
        }
    } else {
        switch (f) {
            inline RGB24, BGR24, RGBA, BGRA => |ff| fullT(ff, false, t, dst, yv, uv, vv, av, w),
            else => unreachable,
        }
    }
}
