        const b: V16i32 = @as(V16u8, @shuffle(u8, v, undefined, comptime strideMask(16, bpp, bo)));
        var y = (r * sp16(ry) + g * sp16(gy) + b * sp16(by) + sp16((32 << 14) + (1 << 8))) >> @splat(9);
        if (x2) y = @min(y + y, sp16(32767));
        dst[i..][0..16].* = @as(V16i16, @intCast(y));
    }
