        const r: i32 = src[bpp * i + ro];
        const g: i32 = src[bpp * i + 1];
        const b: i32 = src[bpp * i + bo];
        const y = (ry * r + gy * g + by * b + (32 << 14) + (1 << 8)) >> 9;
        dst[i] = @intCast(if (x2) @min(y * 2, 32767) else y);
