        const vb: V16i16 = @bitCast(@as(@Vector(8, u32), cp[q * 8 ..][0..8].*));
        acc += madd(va, vb);
    }
    return acc;
}

inline fn hsBlockPat(comptime NP: usize, comptime d: [8]u8, src: [*]const i16, cp: [*]const u32) V8i32 {
    var acc: V8i32 = @splat(0);
