const TA_STD = [4]i16{ 1, 2, 0, -1 };

pub fn vecTableOk(t: *const YuvRgb) bool {
    return t.vec_ok and std.mem.eql(i16, &t.ta, &TA_STD) and t.cy_lo >= 0;
}

inline fn mulTa(c: V16i16, comptime ta: i16) V16i16 {
    return switch (ta) {
        0 => sp16w(0),
        1 => c,
        -1 => sp16w(0) -% c,
        2 => c +% c,
        else => c *% sp16w(ta),
    };
}

/// floor(C * t / 65536) for 0 <= C <= 255, t = ta*65536 + tb
inline fn qmul(t: *const TK, comptime j: usize, c: V16i16) V16i16 {
    return mulTa(c, TA_STD[j]) +% mulhs(c, t.tb[j]);
}

/// clip(((kk * cy) + k) >> 16) evaluated exactly in 16-bit lanes; kk2 = kk + km
inline fn ychan(t: *const TK, comptime j: usize, kk2: V16i16) V16u8 {
    const v = kk2 +% mulhs(kk2, t.cy_lo) +% sp16w(t.kh2[j]);
    return @intCast(@min(@max(v, sp16w(0)), sp16w(255)));
}

