    const qb = qmul(t, 1, U) +% sp16w(t.km[2]);
    const qg = qmul(t, 2, U) +% qmul(t, 3, V) +% sp16w(t.km[1]);
    return .{ .r = ychan(t, 0, Y +% qr), .g = ychan(t, 1, Y +% qg), .b = ychan(t, 2, Y +% qb) };
}

