fn halfT(comptime f: i32, t: *const YuvRgb, dst: [*]u8, yv: []const i32, uv: []const i32, vv: []const i32, w: usize) void {
    const l = comptime layout(f);
    const tk = TK.of(t);
    var i: usize = 0;
    while (vecTableOk(t) and i + 16 <= w) : (i += 16) {
        const Y: V16i32 = yv[i..][0..16].*;
        if (@reduce(.Min, Y) < YV_MIN or @reduce(.Max, Y) > YV_MAX) break;
        const U: V8i32 = uv[i / 2 ..][0..8].*;
        const V: V8i32 = vv[i / 2 ..][0..8].*;
        const c = tableCore(&tk, @intCast(Y), dupW(U), dupW(V));
        store16(f, dst + i * l.bpp, c, @splat(255));
    }
    while (i < w) : (i += 2) {
        const U: usize = @intCast(@min(@max(uv[i / 2], 0), 255));
        const V: usize = @intCast(@min(@max(vv[i / 2], 0), 255));
        const or_ = t.off_r[V];
        const og = t.off_gu[U] + t.off_gv[V];
        const ob = t.off_b[U];
        inline for (0..2) |h| {
            if (i + h < w) {
                const Y = yv[i + h];
                const d = dst + (i + h) * l.bpp;
                d[l.r] = t.yt(Y + or_);
                d[1] = t.yt(Y + og);
                d[l.b] = t.yt(Y + ob);
                if (l.bpp == 4) d[3] = 255;
            }
        }
    }
}

